-- Apparence (d'après le guide Gestor) : menus texte ou icônes, densité des tableaux, couleurs d'impression
-- (nouveaux réglages de parametres) et couleur facultative de chaque événement et profil horaire dans le planning.
ALTER TABLE "parametres" DROP CONSTRAINT "parametres_valeur_valide";--> statement-breakpoint
ALTER TABLE "evenements" ADD COLUMN "couleur" varchar(15);--> statement-breakpoint
ALTER TABLE "profils_horaires" ADD COLUMN "couleur" varchar(15);--> statement-breakpoint
ALTER TABLE "evenements" ADD CONSTRAINT "evenements_couleur_valide" CHECK ("evenements"."couleur" IS NULL OR "evenements"."couleur" IN ('bleu', 'vert', 'orange', 'rouge', 'turquoise', 'rose', 'jaune', 'ardoise'));--> statement-breakpoint
ALTER TABLE "parametres" ADD CONSTRAINT "parametres_valeur_valide" CHECK (("parametres"."cle" = 'theme' AND "parametres"."valeur" IN ('bleu', 'emeraude', 'ocean', 'ardoise', 'personnalise')) OR ("parametres"."cle" = 'police' AND "parametres"."valeur" IN ('hanken', 'inter', 'source_sans', 'atkinson')) OR ("parametres"."cle" = 'taille_texte' AND "parametres"."valeur" IN ('normale', 'grande', 'tres_grande')) OR ("parametres"."cle" = 'menu' AND "parametres"."valeur" IN ('icones', 'texte')) OR ("parametres"."cle" = 'densite' AND "parametres"."valeur" IN ('confortable', 'compacte')) OR ("parametres"."cle" = 'impression' AND "parametres"."valeur" IN ('couleurs', 'gris', 'noir_blanc')) OR ("parametres"."cle" IN ('couleur_primaire', 'couleur_marine', 'couleur_accent', 'couleur_fond') AND "parametres"."valeur" ~ '^#[0-9a-f]{6}$'));--> statement-breakpoint
ALTER TABLE "profils_horaires" ADD CONSTRAINT "profils_horaires_couleur_valide" CHECK ("profils_horaires"."couleur" IS NULL OR "profils_horaires"."couleur" IN ('bleu', 'vert', 'orange', 'rouge', 'turquoise', 'rose', 'jaune', 'ardoise'));